// Writes UI/Layout.lua for a set of values.
function toLua(values) {
	const out = LUA_HEAD.slice();
	for (const e of ENTRIES) {
		if (e.section) {
			out.push("", "\t-- " + e.section);
			continue;
		}
		out.push("\t" + e.key + " = { " + values[e.key].join(", ") + " }, -- " + e.comment);
	}
	out.push("}");
	return out.join("\n") + "\n";
}

// Reads the entries of a Layout.lua: key = { numbers }. Returns { values, unknown, bad }.
function fromLua(text, base) {
	const values = {};
	for (const k of KEYS) values[k] = base[k].slice();
	const unknown = [], bad = [], seen = [];
	const clean = text.replace(/--[^\n]*/g, "");
	const re = /([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\{([^{}]*)\}/g;
	let m;
	while ((m = re.exec(clean))) {
		const key = m[1];
		if (!BY_KEY[key]) { unknown.push(key); continue; }
		const nums = m[2].split(",").map(s => s.trim()).filter(s => s !== "").map(Number);
		if (nums.length !== SIZES[BY_KEY[key].kind] || nums.some(n => !Number.isFinite(n))) { bad.push(key); continue; }
		values[key] = nums.map(n => Math.round(n));
		seen.push(key);
	}
	return { values, unknown, bad, seen };
}


